-- release-target-preflight: migrationId=20261119_mdm_dcc_menu_names; allowedEnvironments=test,backup,prod
SELECT CASE
 WHEN (SELECT COUNT(*) FROM system_menu WHERE parent_id=0 AND path='/mdm' AND type=1 AND status=0 AND deleted=b'0')<>1 THEN 'TARGET_PREFLIGHT_BLOCKED:20261119_mdm_dcc_menu_names:ROOT_CONFLICT'
 WHEN (SELECT COUNT(*) FROM system_menu WHERE parent_id=(SELECT MAX(id) FROM system_menu WHERE parent_id=0 AND path='/mdm' AND type=1 AND status=0 AND deleted=b'0') AND type=2 AND status=0 AND deleted=b'0' AND component IN ('dcc/controlled-file/basic-data/project-code/index','dcc/controlled-file/basic-data/product-catalog/index','dcc/controlled-file/basic-data/file-type-taxonomy/index'))<>3 OR (SELECT COUNT(DISTINCT component) FROM system_menu WHERE type=2 AND status=0 AND deleted=b'0' AND component IN ('dcc/controlled-file/basic-data/project-code/index','dcc/controlled-file/basic-data/product-catalog/index','dcc/controlled-file/basic-data/file-type-taxonomy/index'))<>3 THEN 'TARGET_PREFLIGHT_BLOCKED:20261119_mdm_dcc_menu_names:MENU_IDENTITY_CONFLICT'
 WHEN EXISTS(SELECT 1 FROM system_menu WHERE deleted=b'0' AND component IN ('dcc/controlled-file/basic-data/project-code/index','dcc/controlled-file/basic-data/product-catalog/index','dcc/controlled-file/basic-data/file-type-taxonomy/index') AND name NOT IN ('DCC项目代码','项目代码','DCC产品目录','产品目录','DCC文件分类','文件分类')) THEN 'TARGET_PREFLIGHT_BLOCKED:20261119_mdm_dcc_menu_names:UNEXPECTED_LABEL'
 ELSE 'TARGET_PREFLIGHT_PASS:20261119_mdm_dcc_menu_names' END;
